"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { authenticatedFetch } from "@/lib/auth/api-client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export default function SettingsPage() {
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [emailNotifications, setEmailNotifications] = useState(true);
  const [pushNotifications, setPushNotifications] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // プロフィール情報を取得（認証が完了してから）
  useEffect(() => {
    // 認証がまだ読み込み中の場合は待つ
    if (authLoading) {
      return;
    }

    // 認証されていない場合はローディングを解除
    if (!isAuthenticated) {
      setIsLoading(false);
      return;
    }

    const fetchProfile = async () => {
      try {
        console.log("[SettingsPage] Fetching profile...");
        
        // タイムアウト付きでプロフィール情報を取得
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 10000); // 10秒でタイムアウト

        let response: Response;
        try {
          console.log("[SettingsPage] Calling authenticatedFetch...");
          response = await authenticatedFetch("/api/auth/profile", {
            signal: controller.signal,
          });
          console.log("[SettingsPage] authenticatedFetch completed");
          clearTimeout(timeoutId);
        } catch (fetchError: any) {
          clearTimeout(timeoutId);
          console.error("[SettingsPage] Fetch error:", fetchError);
          if (fetchError.name === "AbortError") {
            console.error("[SettingsPage] Request timeout");
            throw new Error("リクエストがタイムアウトしました");
          }
          throw fetchError;
        }

        console.log("[SettingsPage] Profile response status:", response.status);

        if (response.ok) {
          const data = await response.json();
          console.log("[SettingsPage] Profile data:", data);
          setName(data.name || "");
          setEmail(data.email || "");
        } else {
          const errorData = await response.json().catch(() => ({ error: "Unknown error" }));
          console.error("[SettingsPage] Error response:", errorData);
          toast.error(errorData.error || "プロフィール情報の取得に失敗しました");
        }
      } catch (error: any) {
        console.error("[SettingsPage] Error fetching profile:", error);
        const errorMessage = error?.message || "プロフィール情報の取得に失敗しました";
        toast.error(errorMessage);
      } finally {
        console.log("[SettingsPage] Setting isLoading to false");
        setIsLoading(false);
      }
    };

    fetchProfile();
  }, [isAuthenticated, authLoading]);

  const handleProfileSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const response = await authenticatedFetch("/api/auth/profile", {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ name, email }),
      });

      if (response.ok) {
        const data = await response.json();
        setName(data.name || "");
        setEmail(data.email || "");
        toast.success("プロフィール情報を更新しました");
      } else {
        const error = await response.json();
        toast.error(error.error || "プロフィール情報の更新に失敗しました");
      }
    } catch (error) {
      console.error("Error updating profile:", error);
      toast.error("プロフィール情報の更新に失敗しました");
    } finally {
      setIsSaving(false);
    }
  };

  const handlePasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // バリデーション
    if (newPassword.length < 6) {
      toast.error("新しいパスワードは6文字以上である必要があります");
      return;
    }

    if (newPassword !== confirmPassword) {
      toast.error("新しいパスワードが一致しません");
      return;
    }

    setIsSaving(true);

    try {
      const response = await authenticatedFetch("/api/auth/change-password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          currentPassword,
          newPassword,
        }),
      });

      if (response.ok) {
        toast.success("パスワードを変更しました");
        setCurrentPassword("");
        setNewPassword("");
        setConfirmPassword("");
      } else {
        const error = await response.json();
        toast.error(error.error || "パスワードの変更に失敗しました");
      }
    } catch (error) {
      console.error("Error changing password:", error);
      toast.error("パスワードの変更に失敗しました");
    } finally {
      setIsSaving(false);
    }
  };

  if (authLoading || isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">アカウント設定</h1>
        <p className="text-sm text-gray-600 mt-1">
          アカウント情報と設定を管理します
        </p>
      </div>

      {/* プロフィール情報 */}
      <div className="bg-white rounded-md border">
        <div className="px-6 py-4 border-b">
          <h2 className="text-lg font-semibold">プロフィール情報</h2>
        </div>
        <form onSubmit={handleProfileSubmit} className="p-6 space-y-6">
          <div className="space-y-2">
            <Label htmlFor="name">名前</Label>
            <Input
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="山田 太郎"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="email">メールアドレス</Label>
            <Input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="example@atelier.com"
            />
          </div>

          <div className="flex justify-end">
            <Button type="submit" disabled={isSaving}>
              {isSaving ? "保存中..." : "変更を保存"}
            </Button>
          </div>
        </form>
      </div>

      {/* パスワード変更 */}
      <div className="bg-white rounded-md border">
        <div className="px-6 py-4 border-b">
          <h2 className="text-lg font-semibold">パスワード変更</h2>
        </div>
        <form onSubmit={handlePasswordSubmit} className="p-6 space-y-6">
          <div className="space-y-2">
            <Label htmlFor="currentPassword">現在のパスワード</Label>
            <Input
              id="currentPassword"
              type="password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              placeholder="••••••••"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="newPassword">新しいパスワード</Label>
            <Input
              id="newPassword"
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="••••••••"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="confirmPassword">新しいパスワード（確認）</Label>
            <Input
              id="confirmPassword"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="••••••••"
            />
          </div>

          <div className="flex justify-end">
            <Button type="submit" disabled={isSaving}>
              {isSaving ? "保存中..." : "パスワードを変更"}
            </Button>
          </div>
        </form>
      </div>

      {/* 通知設定 */}
      <div className="bg-white rounded-md border">
        <div className="px-6 py-4 border-b">
          <h2 className="text-lg font-semibold">通知設定</h2>
        </div>
        <div className="p-6 space-y-6">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label htmlFor="emailNotifications">メール通知</Label>
              <p className="text-sm text-gray-500">
                重要な更新をメールで受け取る
              </p>
            </div>
            <Switch
              id="emailNotifications"
              checked={emailNotifications}
              onCheckedChange={setEmailNotifications}
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label htmlFor="pushNotifications">プッシュ通知</Label>
              <p className="text-sm text-gray-500">
                ブラウザのプッシュ通知を受け取る
              </p>
            </div>
            <Switch
              id="pushNotifications"
              checked={pushNotifications}
              onCheckedChange={setPushNotifications}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
